<script lang="ts">
	import { register } from "@/lib/api/auth";
	import { apiErrorMessage } from "@/lib/api/client";
	let username = "", password = "", confirm = "", nickname = "", email = "", error = "", busy = false;
	async function submit() { error = ""; if (username.trim().length < 3 || password.length < 6 || password !== confirm || !nickname.trim()) { error = "请检查账号、密码、确认密码和昵称"; return; } busy = true; try { await register({ username: username.trim(), password, nickname: nickname.trim(), email: email.trim() || undefined }); window.location.href = "/"; } catch (cause) { error = apiErrorMessage(cause, "注册失败，请检查输入"); } finally { busy = false; } }
</script>
<form on:submit|preventDefault={submit}><label>账号<input bind:value={username} autocomplete="username" required minlength="3" maxlength="32" /></label><label>昵称<input bind:value={nickname} required maxlength="64" /></label><label>邮箱<input bind:value={email} type="email" autocomplete="email" /></label><label>密码<input bind:value={password} type="password" autocomplete="new-password" required minlength="6" maxlength="32" /></label><label>确认密码<input bind:value={confirm} type="password" required minlength="6" maxlength="32" /></label>{#if error}<p role="alert">{error}</p>{/if}<button type="submit" disabled={busy}>{busy ? "注册中..." : "注册"}</button><a href="/login/">已有账号，去登录</a></form>
<style>form{display:grid;gap:1rem;max-width:24rem;margin:auto;padding:1.5rem;border:1px solid var(--line-divider);border-radius:.5rem}label{display:grid;gap:.35rem}input{padding:.6rem;border:1px solid var(--line-divider);border-radius:.25rem;background:transparent}button{padding:.6rem;background:var(--primary);color:#fff;border-radius:.25rem}button:disabled{opacity:.5}p{margin:0;color:#c33}a{color:var(--primary);text-align:center}</style>
